	// A: i x k
	// B: k x j
	using namespace noarr;

	// Tunable block sizes for cache-friendly tiling in j and k dimensions.
	// These are compile-time constants so the compiler can optimize aggressively.
	constexpr std::size_t J_BLOCK = 64;
	constexpr std::size_t K_BLOCK = 64;

