	// 2) Blocked GEMM:
	//
	// We tile the k and j dimensions:
	//   - into_blocks_dynamic<'k','K','k','rk'>(K_BLOCK)
	//       splits k into block index K and intra-block index k, with
	//       rk indicating whether a given (K,k) is within bounds.
	//   - into_blocks_dynamic<'j','J','j','rj'>(J_BLOCK)
	//       splits j into block index J and intra-block index j, with
	//       rj indicating whether a given (J,j) is within bounds.
	//
