		noarr::into_blocks_dynamic<'k', 'K', 'k', 'rk'>(noarr::lit<K_BLOCK>) ^
		noarr::into_blocks_dynamic<'j', 'J', 'j', 'rj'>(noarr::lit<J_BLOCK>);

