		// Filter valid k-indices inside the current K-block
		ijk_block.template for_dims<'rk'>([&](auto k_present_block) {
			// For each valid k (within this block)
			k_present_block.template for_dims<'k'>([&](auto k_trav) {
				// Precompute alpha * A[i][k] once per (i,k) pair to
				// reduce the number of floating-point multiplications.
				num_t a_scaled = alpha * A[k_trav];

				// Filter valid j-indices inside the current J-block
				k_trav.template for_dims<'rj'>([&](auto j_present_block) {
					// Finally, iterate over all valid j in this tile
					j_present_block.for_each([&](auto state) {
						// state contains i, j, k (and other fixed indices)
						// C[i][j] += alpha * A[i][k] * B[k][j]
						C[state] += a_scaled * B[state];
					});
				});
			});
		});
	});
#pragma endscop
