// include benchmark-specific definitions
#include "gemm.hpp"

using num_t = DATA_TYPE;

namespace {

// basic 1D dimension protos
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

// Layout tuning: choose memory order of dimensions
// C: i x j  -> dims ('i','j') with j contiguous
// A: i x k  -> dims ('i','k') with k contiguous
// B: k x j  -> dims ('k','j') with j contiguous
struct tuning {
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec); // C: i x j
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec); // A: i x k
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ k_vec); // B: k x j
} tuning;

// ---------------------------------------------------------------------------
// Array initialization
// ---------------------------------------------------------------------------
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	// C: i x j
	// A: i x k
	// B: k x j
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// Pre-compute lengths once; they are invariant inside the traversals.
	const std::size_t ni = C | get_length<'i'>();
	const std::size_t nk = A | get_length<'k'>();
	const std::size_t nj = B | get_length<'j'>();

	// C[i][j] = (i*j+1) % ni / ni
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 1) % ni) / ni;
	});

	// A[i][k] = i*(k+1) % nk / nk
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)(i * (k + 1) % nk) / nk;
	});

	// B[k][j] = k*(j+2) % nj / nj
	traverser(B).for_each([=](auto state) {
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = (num_t)(k * (j + 2) % nj) / nj;
	});
}

// ---------------------------------------------------------------------------
// Main computational kernel (GEMM)
// Form C := alpha*A*B + beta*C,
// A is NIxNK, B is NKxNJ, C is NIxNJ
//
// Optimizations vs. baseline:
//  - Split scaling C by beta into a dedicated pass over C (better cache
//    behavior, more obvious to the optimizer).
//  - Use a clear loop order i-k-j implemented via Noarr traversers:
//
//        for i
//          for k
//            tmp = alpha * A[i,k];
//            for j
//              C[i,j] += tmp * B[k,j];
//
//    This loop order reuses A[i,k] across all j, and keeps accesses to B and C
//    in their innermost (contiguous) 'j' dimension, improving locality.
//  - Hoisting alpha * A[i,k] out of the innermost j-loop reduces multiplications.
// ---------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_gemm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	// C: i x j
	// A: i x k
	// B: k x j
	using namespace noarr;

#pragma scop
	// ---------------------------------------------------------------------
	// 1) Scale C by beta: C[i][j] *= beta
	//    One simple pass over C; completely independent of A and B.
	// ---------------------------------------------------------------------
	traverser(C).for_each([=](auto state) {
		C[state] *= beta;
	});

	// ---------------------------------------------------------------------
	// 2) Accumulate alpha * A * B into C.
	//
	//    We traverse A, B, C together with outer dimensions ('i','k'):
	//      - 'i'  : row index of C and A
	//      - 'k'  : shared dimension between A and B
	//
	//    For each fixed (i,k) pair, we:
	//      - read A[i,k] once,
	//      - precompute alpha * A[i,k],
	//      - then traverse all 'j' to update C[i,j] using B[k,j].
	//
	//    This realizes loop order: i (outer) -> k (middle) -> j (inner).
	// ---------------------------------------------------------------------
	traverser(A, B, C).template for_dims<'i', 'k'>([=](auto trav_ik) {
		// trav_ik has 'i' and 'k' fixed; 'j' is the remaining dimension.

		// Load A[i,k] once and precompute the scaled value.
		const num_t a_ik        = A[trav_ik];
		const num_t alpha_a_ik  = alpha * a_ik;

		// Now iterate 'j' for this fixed (i,k).
		trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
			// trav_ikj has 'i', 'k', 'j' all fixed.
