#include "gemm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec); // C: i x j
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec); // A: i x k
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ k_vec); // B: k x j
} tuning;

// Array initialization
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	// C: i x j
	// A: i x k
	// B: k x j
	using namespace noarr;

	alpha = (num_t)1.5;
	beta = (num_t)1.2;

	// Precompute lengths once instead of inside every lambda iteration
	const std::size_t ni = C | get_length<'i'>();
	const std::size_t nk = A | get_length<'k'>();
	const std::size_t nj = B | get_length<'j'>();

	// C[i][j] = (i*j+1) % ni / ni
	traverser(C).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 1) % ni) / (num_t)ni;
	});

	// A[i][k] = i*(k+1) % nk / nk
	traverser(A).for_each([&](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)(i * (k + 1) % nk) / (num_t)nk;
	});

	// B[k][j] = k*(j+2) % nj / nj
	traverser(B).for_each([&](auto state) {
		auto [k, j] = get_indices<'k', 'j'>(state);
		B[state] = (num_t)(k * (j + 2) % nj) / (num_t)nj;
	});
}

// Main computational kernel (GEMM)
// Form C := alpha*A*B + beta*C,
// A is NIxNK, B is NKxNJ, C is NIxNJ
//
// Optimized for:
//   - better cache locality: inner loop walks C and B along contiguous 'j'
//   - fewer memory loads: each A(i,k) is loaded once per (i,k) and
//     reused across all j in that row of B / C
[[gnu::flatten, gnu::noinline]]
void kernel_gemm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	// C: i x j
	// A: i x k
	// B: k x j
	using namespace noarr;

#pragma scop

	// 1) Scale C by beta.
	//    Stand-alone traversal keeps the kernel simple and touches C
	//    in the natural (i,j) storage order (j is the innermost dim).
	traverser(C).for_each([&](auto state) {
		C[state] *= beta;
	});

	// 2) GEMM part: C += alpha * A * B
	//
	// We iterate in i–k–j order:
	//   for i:
	//     for k:
	//       a_ik = A[i,k]
	//       for j:
	//         C[i,j] += alpha * a_ik * B[k,j]
	//
	// Reasons:
	//   - j is innermost -> contiguous access in both C (i,j) and B (k,j)
	//   - A[i,k] is invariant across j, so we read it once per (i,k)
	//     and reuse it for the whole j-row, reducing memory traffic.

	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed; remaining relevant dims are 'k' and 'j'

		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// trav_ik has both 'i' and 'k' fixed; only 'j' remains free

			// State with current (i,k); used to read A(i,k) once
			auto ik_state = trav_ik.state();
			const num_t a_ik = A[ik_state];
			const num_t alpha_a_ik = alpha * a_ik;

			// Inner-most traversal over 'j' only. The state here contains
			// (i,j,k), but C ignores 'k' and B ignores 'i', so this works
			// for all three bags simultaneously.
			trav_ik.for_each([&](auto state) {
				C[state] += alpha_a_ik * B[state];
			});
		});
	});

#pragma endscop
}

} // namespace

